//! # akatsuki-shortcuts
//!
//! The one key map (BRIEF "Keyboard-first"): `packages/shortcuts/shortcuts.json` is the source,
//! its build script (`pnpm --filter @akatsuki/shortcuts build`) writes [`generated`] — never edit
//! that file by hand. Every action is reachable by key and by the command palette.

// Generated by packages/shortcuts/scripts/build.ts; rustfmt is skipped so `pnpm shortcuts:build` and
// `cargo fmt --check` never disagree about its layout (same rule as crates/tokens, D-380).
#[rustfmt::skip]
#[allow(missing_docs, clippy::all)]
mod generated;

pub use generated::*;

impl Platform {
    /// The platform this binary was built for.
    pub const fn current() -> Self {
        if cfg!(target_os = "macos") {
            Platform::Mac
        } else if cfg!(target_os = "windows") {
            Platform::Windows
        } else {
            Platform::Linux
        }
    }
}

/// `(shortcut, keystrokes)` pairs for binding in GPUI, for one key map on the current platform.
pub fn gpui_bindings(keymap: Keymap) -> impl Iterator<Item = (&'static Shortcut, &'static str)> {
    let platform = Platform::current();
    SHORTCUTS.iter().flat_map(move |s| s.keys_for(keymap).gpui_for_platform(platform).iter().map(move |k| (s, *k)))
}

/// Shortcuts listed in the command palette.
pub fn palette_entries() -> impl Iterator<Item = &'static Shortcut> {
    SHORTCUTS.iter().filter(|s| s.palette)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn ids_are_unique_and_findable() {
        let mut seen = HashSet::new();
        for s in SHORTCUTS {
            assert!(seen.insert(s.id), "duplicate {}", s.id);
            assert_eq!(find(s.id).map(|f| f.id), Some(s.id));
            assert!(!s.label.trim().is_empty());
        }
        assert!(find("does.not.exist").is_none());
    }

    #[test]
    fn every_shortcut_is_reachable() {
        for s in SHORTCUTS {
            let has_key = !s.keys.for_platform(Platform::current()).is_empty();
            assert!(has_key || s.palette, "{} is unreachable", s.id);
        }
    }

    #[test]
    fn gpui_keystrokes_have_no_plus_syntax() {
        for keymap in [Keymap::Superhuman, Keymap::Gmail] {
            for (s, k) in gpui_bindings(keymap) {
                assert!(!k.is_empty(), "{}", s.id);
                assert!(!k.contains("+") || k == "+" || k.ends_with("-+"), "{}: {k}", s.id);
            }
        }
        assert!(palette_entries().count() > 0);
    }
}
